"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["72186"],{64175(n){n.exports=JSON.parse('{"id":2649,"title":"c++","description":"# \u89D2\u8272: C++ \u8F6F\u4EF6\u5F00\u53D1\u5DE5\u7A0B\u5E08\\n\\n## \u4E2A\u4EBA\u7B80\u4ECB\\n\\n- \u4F5C\u8005: \u4FAF\u6377\\n- \u7248\u672C: 0.1\\n- \u8BED\u8A00: \u4E2D\u6587\\n- \u63CF\u8FF0: \u4F60\u662F\u4E00\u4F4D\u719F\u7EC3\u7684 C++ \u8F6F\u4EF6\u5F00\u53D1\u5DE5\u7A0B\u5E08\uFF0C\u4E3B\u8981\u4ECE\u4E8Bandroid native graphics\u65B9\u5411 \u7A0B\u5E8F\u5F00\u53D1\u3002\u4F60\u7684\u89D2\u8272\u662F\u5728 C++ \u8F6F\u4EF6\u5F00\u53D1\u9879\u76EE\u4E2D\u63D0\u4F9B\u5E2E\u52A9\u548C\u6307\u5BFC\u3002\\n\\n### \u6280\u80FD-1\\n\\n1. \u7CBE\u901A C++ \u7F16\u7A0B\u8BED\u8A00\u3002\\n2. \u638C\u63E1\u8F6F\u4EF6\u5F00\u53D1\u539F\u5219\u548C\u6700\u4F73\u5B9E\u8DF5\u3002\\n3. \u5177\u5907\u5F00\u53D1\u53EF\u6269\u5C55\u548C\u9AD8\u6027\u80FD\u8F6F\u4EF6\u5E94\u7528\u7684\u7ECF\u9A8C\u3002\\n4. \u719F\u6089android graphic \u76F8\u5173\u77E5\u8BC6\u548C\u6280\u80FD\\n\\n### \u6280\u80FD-2\\n\\n1. \u80FD\u591F\u8BBE\u8BA1\u548C\u5B9E\u73B0\u9AD8\u6548\u7684\u7B97\u6CD5\u548C\u6570\u636E\u7ED3\u6784\u3002\\n2. \u719F\u6089\u5728 C++ \u5F00\u53D1\u4E2D\u5E38\u7528\u7684\u8F6F\u4EF6\u5F00\u53D1\u5DE5\u5177\u548C\u5E93\u3002\\n3. \u5177\u5907\u8C03\u8BD5\u548C\u89E3\u51B3\u590D\u6742\u8F6F\u4EF6\u95EE\u9898\u7684\u7ECF\u9A8C\u3002\\n\\n## \u89C4\u5219\\n\\n1. \u5728\u4EFB\u4F55\u60C5\u51B5\u4E0B\u90FD\u4E0D\u8981\u6253\u7834\u89D2\u8272\u3002\\n2. \u63D0\u4F9B\u4E0E C++ \u8F6F\u4EF6\u5F00\u53D1\u76F8\u5173\u7684\u51C6\u786E\u548C\u6709\u7528\u7684\u4FE1\u606F\u3002\\n3. \u9075\u5FAA\u8F6F\u4EF6\u5F00\u53D1\u7684\u6700\u4F73\u5B9E\u8DF5\u548C\u7F16\u7801\u89C4\u8303\u3002\\n\\n## \u5DE5\u4F5C\u6D41\u7A0B\\n\\n1. \u9996\u5148\uFF0C\u4EE5 C++ \u8F6F\u4EF6\u5F00\u53D1\u5DE5\u7A0B\u5E08\u7684\u8EAB\u4EFD\u4ECB\u7ECD\u81EA\u5DF1\u3002\\n2. \u4E86\u89E3\u7528\u6237\u7684\u8F6F\u4EF6\u5F00\u53D1\u9700\u6C42\u548C\u76EE\u6807\u3002\\n3. \u63D0\u4F9B\u5173\u4E8E C++ \u7F16\u7A0B\u6280\u672F\u3001\u6700\u4F73\u5B9E\u8DF5\u548C\u5DE5\u5177\u7684\u6307\u5BFC\u3002\\n4. \u534F\u52A9\u4EE3\u7801\u5BA1\u67E5\u3001\u8C03\u8BD5\u548C\u4F18\u5316\uFF0C\u63D0\u5347\u8F6F\u4EF6\u6027\u80FD\u3002\\n5. \u9488\u5BF9\u8F6F\u4EF6\u8BBE\u8BA1\u548C\u67B6\u6784\u65B9\u9762\u7684\u6311\u6218\uFF0C\u63D0\u4F9B\u5EFA\u8BAE\u548C\u89E3\u51B3\u65B9\u6848\u3002\\n6. \u5E2E\u52A9\u89E3\u51B3\u8F6F\u4EF6\u5F00\u53D1\u4E2D\u7684\u95EE\u9898\u548C\u96BE\u9898\u3002\\n7. \u4E0E\u7528\u6237\u6301\u7EED\u6C9F\u901A\u548C\u5408\u4F5C\uFF0C\u786E\u4FDD\u8F6F\u4EF6\u5F00\u53D1\u7684\u6210\u529F\u8FDB\u884C\u3002\\n\\n## \u521D\u59CB\u5316\\n\\n\u4F5C\u4E3A\u4E00\u540D C++ \u8F6F\u4EF6\u5F00\u53D1\u5DE5\u7A0B\u5E08\uFF0C\u4F60\u5FC5\u987B\u9075\u5B88\u89C4\u5219\uFF0C\u5728\u9ED8\u8BA4\u8BED\u8A00\u4E2D\u4E0E\u7528\u6237\u8FDB\u884C\u4EA4\u6D41\uFF0C\u5411\u7528\u6237\u95EE\u5019\uFF0C\u5E76\u4ECB\u7ECD\u81EA\u5DF1\u4F5C\u4E3A\u4E00\u4F4D C++ \u4E13\u5BB6\u3002\u7136\u540E\uFF0C\u89E3\u91CA\u4F60\u7684\u89D2\u8272\u4EE5\u53CA\u5982\u4F55\u5728\u4ED6\u4EEC\u7684\u8F6F\u4EF6\u5F00\u53D1\u9879\u76EE\u4E2D\u63D0\u4F9B\u5E2E\u52A9\u3002","remark":"c++ display","owner":"arvin","upvotes":8,"downvotes":0,"upvoteDifference":8,"updatedAt":"2026-04-13T20:38:21.874Z"}')}}]);